import { Injectable, inject } from '@angular/core';
import { HttpClient, HttpHeaders } from '@angular/common/http';
import { finalize, map, Observable, of, shareReplay, tap } from 'rxjs';

/**
 * Public prototype ONLY: each browser receives its own signed and expiring
 * pseudonymous demo driver. This is not verified login and processes no payments.
 * Tokens are generated by Spring Boot; no backend secret is bundled in Angular.
 */
@Injectable({ providedIn: 'root' })
export class BillingDemoSession {
  private readonly http = inject(HttpClient);
  private readonly storageKey = 'rumbo.billing.demo-session.v1';
  private currentToken: string | null = null;
  private pending?: Observable<string>;

  token(): Observable<string> {
    const saved = this.currentToken ?? this.read();
    if (saved) return of(saved);
    if (!this.pending) {
      this.pending = this.http.post<{ token: string }>('/api/v1/billing-demo/session', {})
        .pipe(
          map(response => response.token),
          tap(token => {
            this.currentToken = token;
            try { localStorage.setItem(this.storageKey, token); } catch { /* no storage */ }
          }),
          finalize(() => { this.pending = undefined; }),
          shareReplay({ bufferSize: 1, refCount: false }),
        );
    }
    return this.pending;
  }

  headers(token: string): HttpHeaders {
    return new HttpHeaders({ Authorization: 'Bearer ' + token });
  }

  clear(): void {
    this.currentToken = null;
    try { localStorage.removeItem(this.storageKey); } catch { /* no storage */ }
  }

  private read(): string | null {
    try { return localStorage.getItem(this.storageKey); } catch { return null; }
  }
}
